export const ALL_LEARN_TOPICS: (LearnTopic & { sectionId: string; sectionTitle: string; groupTitle: string })[] = LEARN_SECTIONS.flatMap((section) =>
  section.groups.flatMap((group) =>
    group.topics.map((topic) => ({ ...topic, sectionId: section.id, sectionTitle: section.title, groupTitle: group.title }))
  )
);

export function getLearnTopic(slug: string) {
  return ALL_LEARN_TOPICS.find((t) => t.slug === slug) ?? null;
}

export function learnTopicCount(): number {
  return ALL_LEARN_TOPICS.length;
}
